powerpagecomponent.content:
{
  "source": "{% comment %}
sections--acceptance-course

Parameters (from router via include):
  acceptanceId  - acceptance record GUID
  offeringName  - offering display name
  debug         - debug mode flag

Architecture:
  Router-integrated — receives acceptanceId from sections--acceptance-router.
  Fetches acceptance + linked offering (single query with join).
  Reads hit_courseaccessaudience + hit_courseaccessplan from offering
  to derive form configuration via JavaScript AUDIENCE_CONFIG object.
  PATCHes hit_offeringacceptances with contact fields + audience + plan.
  No status written — Power Automate handles PENDING_PAYMENT / COMPLETED.
  Redirects back through router with waitforpayment=1 (donation retry pattern).

Audience → Field groups shown:
  individual          → contact, postcode
  organisation        → contact, postcode, organisation
  organisation-member → contact, postcode, redemption

Adding a new audience: add one entry to AUDIENCE_CONFIG in the JS block only.
{% endcomment %}

{% assign DEBUG = debug | default: request.params.debug == '1' %}
{% assign acceptanceId = acceptanceId | default: request.params.acceptanceid | default: '' | strip %}
{% assign offeringName = offeringName | default: '' | strip %}

{%- comment -%} Copy defaults — all overridable via include params {%- endcomment -%}
{% assign acceptanceTypeLabel  = acceptanceTypeLabel  | default: 'Course Registration' %}
{% assign formTitle            = formTitle            | default: 'Complete your registration' %}
{% assign formSubtitle         = formSubtitle         | default: 'Confirm your details to secure your access.' %}
{% assign progressText         = progressText         | default: 'Enter your details to continue' %}
{% assign submitButtonText     = submitButtonText     | default: 'Confirm Registration' %}
{% assign submittingButtonText = submittingButtonText | default: 'Saving...' %}

{% if acceptanceId == '' %}
  <div class="hit-alert hit-alert-warning" role="alert">Missing acceptance id.</div>
{% else %}

  {% fetchxml acc_q %}
  <fetch top="1" mapping="logical">
    <entity name="hit_offeringacceptance">
      <attribute name="hit_offeringacceptanceid" />
      <attribute name="hit_firstname" />
      <attribute name="hit_lastname" />
      <attribute name="hit_email" />
      <attribute name="hit_mobilephone" />
      <attribute name="hit_postcode" />
      <attribute name="hit_organisationinput" />
      <attribute name="hit_contactroleinput" />
      <attribute name="hit_redemptioncode" />
      <attribute name="hit_courseaccessaudience" />
      <attribute name="hit_courseaccessplan" />
      <filter>
        <condition attribute="hit_offeringacceptanceid" operator="eq" value="{{ acceptanceId | escape }}" />
      </filter>
      <link-entity name="hit_offering"
                   from="hit_offeringid"
                   to="hit_offering"
                   alias="off"
                   link-type="outer">
        <attribute name="hit_offeringname" />
        <attribute name="hit_displaytitle" />
        <attribute name="hit_formdescription" />
        <attribute name="hit_formheadline" />
        <attribute name="hit_formsummary" />
        <attribute name="hit_description" />
        <attribute name="hit_imageurl" />
        <attribute name="hit_fixedprice" />
        <attribute name="hit_courseaccessaudience" />
        <attribute name="hit_courseaccessplan" />
      </link-entity>
    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign acc = acc_q.results.entities | first %}

  {% if acc == nil %}
    <div class="hit-alert hit-alert-warning" role="alert">Acceptance not found.</div>
  {% else %}

    {%- comment -%} Offering fields (via join alias 'off') {%- endcomment -%}
    {% assign offeringName = acc['off.hit_offeringname'] | default: offeringName | default: acceptanceTypeLabel %}
    {% assign leftTitle = acc['off.hit_displaytitle'] | default: offeringName | default: acceptanceTypeLabel | strip %}
    {% assign leftDescriptionHtml = acc['off.hit_formdescription'] | default: '' | strip %}
    {% assign formTitle = acc['off.hit_formheadline'] | default: formTitle | strip %}
    {% assign formSubtitle = acc['off.hit_formsummary'] | default: formSubtitle | strip %}
    {% assign offeringDesc = acc['off.hit_description']  | default: '' %}
    {% assign heroImageUrl = acc['off.hit_imageurl']     | default: '' | strip %}

    {% assign fixedPrice = acc['off.hit_fixedprice'] | default: 0 %}
    {% if fixedPrice.value %}{% assign fixedPrice = fixedPrice.value %}{% endif %}

    {%- comment -%} Audience — from offering (drives form configuration) {%- endcomment -%}
    {% assign aud_raw   = acc['off.hit_courseaccessaudience'] %}
    {% assign aud_value = aud_raw.value | default: aud_raw | default: '' %}
    {% assign aud_label = aud_raw.label | default: acc['off.hit_courseaccessaudience@OData.Community.Display.V1.FormattedValue'] | default: '' %}
    {% assign aud_slug  = aud_label | downcase | replace: ' ', '-' %}

    {%- comment -%} Plan — from offering {%- endcomment -%}
    {% assign plan_raw   = acc['off.hit_courseaccessplan'] %}
    {% assign plan_value = plan_raw.value | default: plan_raw | default: '' %}
    {% assign plan_label = plan_raw.label | default: acc['off.hit_courseaccessplan@OData.Community.Display.V1.FormattedValue'] | default: '' %}
    {% assign plan_slug  = plan_label | downcase | replace: ' ', '-' %}

    {%- comment -%}
    If audience/plan already stored on acceptance (re-entry), use those values.
    Offering values are authoritative for form configuration; acceptance values
    are used for pre-population only.
    {%- endcomment -%}
    {% assign acc_aud_raw   = acc.hit_courseaccessaudience %}
    {% assign acc_aud_value = acc_aud_raw.value | default: acc_aud_raw | default: '' %}
    {% assign acc_plan_raw  = acc.hit_courseaccessplan %}
    {% assign acc_plan_value = acc_plan_raw.value | default: acc_plan_raw | default: '' %}
    {% if acc_aud_value  != '' %}{% assign aud_value  = acc_aud_value  %}{% endif %}
    {% if acc_plan_value != '' %}{% assign plan_value = acc_plan_value %}{% endif %}

    {%- comment -%} Left panel "What happens next" copy — overridable via param {%- endcomment -%}
    {% assign whatHappensNext = whatHappensNext | default: '' %}
    {% if whatHappensNext == '' %}
      {% if plan_slug == 'pwd' %}
        {% assign whatHappensNext = "Your registration is free. Once confirmed you'll receive your access details by email." %}
      {% elsif plan_slug == 'org-member' %}
        {% assign whatHappensNext = "Enter your redemption code to join your organisation's access plan." %}
      {% elsif plan_slug == 'partner' %}
        {% assign whatHappensNext = "Once payment is confirmed, your organisation will receive a redemption code for staff access." %}
      {% else %}
        {% assign whatHappensNext = "Complete your details to continue to the next step." %}
      {% endif %}
    {% endif %}

    {% if DEBUG %}
    <div class="hit-debug-panel">
      ✅ sections--acceptance-course<br>
      acceptanceId={{ acceptanceId | escape }}<br>
      offeringName={{ offeringName | escape }}<br>
      audience={{ aud_label | escape }} ({{ aud_value }}) → {{ aud_slug }}<br>
      plan={{ plan_label | escape }} ({{ plan_value }}) → {{ plan_slug }}<br>
      fixedPrice={{ fixedPrice }}<br>
      heroImageUrl={{ heroImageUrl | escape }}
    </div>
    {% endif %}

    <div class="hit-acceptance hit-acceptance--course"
         data-context="course"
         data-acceptance-id="{{ acc.hit_offeringacceptanceid | escape }}">

      <div class="hit-acceptance__grid">

        <!-- =====================================================
             LEFT: COURSE SUMMARY
             ===================================================== -->
        <aside class="hit-acceptance__left">
          <div class="hit-card hit-acceptance__summary-card">

            {% if heroImageUrl != '' %}
              <img src="{{ heroImageUrl | escape }}"
                   alt="{{ offeringName | escape }}"
                   class="hit-acceptance__hero-image" />
            {% endif %}

            <h1 class="hit-acceptance__title">{{ leftTitle | escape }}</h1>

            {% if leftDescriptionHtml != '' %}
              <div class="hit-acceptance__description hit-rich-text-description">{{ leftDescriptionHtml }}</div>
            {% endif %}

          </div>
        </aside>

        <!-- =====================================================
             RIGHT: REGISTRATION FORM
             ===================================================== -->
        <main class="hit-acceptance__right">
          <div class="hit-card hit-form-card">

            <h2 class="hit-heading">{{ formTitle | escape }}</h2>
            <p class="hit-subtitle">{{ formSubtitle | escape }}</p>

            <div class="hit-status-pill" aria-label="Current step">
              <span class="hit-status-pill__indicator" aria-hidden="true"></span>
              <span>{{ progressText | escape }}</span>
            </div>

            <input type="hidden" id="caAcceptanceId"
                   value="{{ acc.hit_offeringacceptanceid | escape }}" />

            {%- comment -%} Config data bridge: Liquid values → JavaScript {%- endcomment -%}
            <div id="caConfig"
                 data-audience="{{ aud_slug | escape }}"
                 data-plan="{{ plan_slug | escape }}"
                 data-audience-value="{{ aud_value | escape }}"
                 data-plan-value="{{ plan_value | escape }}"
                 data-price="{{ fixedPrice | escape }}"
                 hidden>
            </div>

            <div id="caErrSummary"
                 class="hit-error-summary"
                 role="alert"
                 aria-atomic="true"
                 hidden>
              <h3 class="hit-error-summary__title">There's a problem</h3>
              <ul id="caErrList" class="hit-error-summary__list"></ul>
            </div>

            <form class="hit-form" id="caForm" novalidate>

              <!-- -----------------------------------------------
                   FIELD GROUP: contact (always shown)
                   ----------------------------------------------- -->
              <div class="hit-form-section" data-field-group="contact">

                <div class="hit-field-row hit-field-row--two">
                  <div class="hit-field">
                    <label class="hit-label" for="caFirstName">
                      First name <span class="hit-required" aria-hidden="true">*</span>
                    </label>
                    <input class="hit-input" type="text" id="caFirstName"
                           value="{{ acc.hit_firstname | default: '' | escape }}"
                           autocomplete="given-name"
                           required aria-required="true" />
                    <p class="hit-error-message" id="caFirstNameErr" role="alert" hidden></p>
                  </div>
                  <div class="hit-field">
                    <label class="hit-label" for="caLastName">
                      Last name <span class="hit-required" aria-hidden="true">*</span>
                    </label>
                    <input class="hit-input" type="text" id="caLastName"
                           value="{{ acc.hit_lastname | default: '' | escape }}"
                           autocomplete="family-name"
                           required aria-required="true" />
                    <p class="hit-error-message" id="caLastNameErr" role="alert" hidden></p>
                  </div>
                </div>

                <div class="hit-field">
                  <label class="hit-label" for="caEmail">
                    Email address <span class="hit-required" aria-hidden="true">*</span>
                  </label>
                  <input class="hit-input" type="email" id="caEmail"
                         value="{{ acc.hit_email | default: '' | escape }}"
                         autocomplete="email"
                         required aria-required="true" />
                  <p class="hit-error-message" id="caEmailErr" role="alert" hidden></p>
                </div>

                <div class="hit-field">
                  <label class="hit-label" for="caMobile">Mobile number</label>
                  <input class="hit-input" type="tel" id="caMobile"
                         value="{{ acc.hit_mobilephone | default: '' | escape }}"
                         autocomplete="tel" />
                </div>

              </div>

              <!-- -----------------------------------------------
                   FIELD GROUP: postcode (always shown)
                   ----------------------------------------------- -->
              <div class="hit-form-section" data-field-group="postcode">

                <div class="hit-field">
                  <label class="hit-label" for="caPostcode">
                    Postcode <span class="hit-required" aria-hidden="true">*</span>
                  </label>
                  <input class="hit-input" type="text" id="caPostcode"
                         value="{{ acc.hit_postcode | default: '' | escape }}"
                         autocomplete="postal-code"
                         inputmode="numeric" maxlength="4"
                         required aria-required="true" />
                  <p class="hit-error-message" id="caPostcodeErr" role="alert" hidden></p>
                </div>

              </div>

              <!-- -----------------------------------------------
                   FIELD GROUP: organisation (Audience = Organisation)
                   ----------------------------------------------- -->
              <div class="hit-form-section" data-field-group="organisation" hidden>

                <div class="hit-field">
                  <label class="hit-label" for="caOrgName">
                    Organisation name <span class="hit-required" aria-hidden="true">*</span>
                  </label>
                  <input class="hit-input" type="text" id="caOrgName"
                         value="{{ acc.hit_organisationinput | default: '' | escape }}"
                         autocomplete="organization" />
                  <p class="hit-error-message" id="caOrgNameErr" role="alert" hidden></p>
                </div>

                <div class="hit-field">
                  <label class="hit-label" for="caOrgRole">
                    Primary contact role <span class="hit-required" aria-hidden="true">*</span>
                  </label>
                  <input class="hit-input" type="text" id="caOrgRole"
                         value="{{ acc.hit_contactroleinput | default: '' | escape }}"
                         autocomplete="organization-title" />
                  <p class="hit-error-message" id="caOrgRoleErr" role="alert" hidden></p>
                </div>

              </div>

              <!-- -----------------------------------------------
                   FIELD GROUP: redemption (Audience = Organisation Member)
                   ----------------------------------------------- -->
              <div class="hit-form-section" data-field-group="redemption" hidden>

                <div class="hit-field">
                  <label class="hit-label" for="caRedemption">
                    Redemption code <span class="hit-required" aria-hidden="true">*</span>
                  </label>
                  <input class="hit-input" type="text" id="caRedemption"
                         value="{{ acc.hit_redemptioncode | default: '' | escape }}"
                         autocomplete="off"
                         placeholder="Enter your organisation's access code" />
                  <p class="hit-error-message" id="caRedemptionErr" role="alert" hidden></p>
                </div>

              </div>

            </form>

           
            <div class="hit-form-actions">
              <button type="button"
                      id="caSubmitBtn"
                      class="hit-button hit-button--primary">
                {{ submitButtonText | escape }}
              </button>
            </div>

          </div>
        </main>

      </div>
    </div>

    <style>
    /* ========================================
       COURSE SUMMARY CARD (LEFT PANEL)
       ======================================== */

    .hit-acceptance__hero-image {
      margin: -20px -20px 20px;
      width: 100%;
      display: block;
      aspect-ratio: 16/9;
      object-fit: cover;
      overflow: hidden;
    }

    .hit-acceptance__badges {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin: 8px 0 14px;
    }

    .hit-acceptance__badge {
      display: inline-block;
      padding: 3px 10px;
      border-radius: 999px;
      font-size: 12px;
      font-weight: 700;
      background: #f3f4f6;
      color: #374151;
      border: 1px solid #e5e7eb;
    }

    .hit-acceptance__badge--secondary {
      background: #eff6ff;
      color: #1d4ed8;
      border: 1px solid #bfdbfe;
    }

    .hit-acceptance__description {
      width: 100%;
      max-width: 100%;
      min-width: 0;
      font-size: 14px;
      line-height: 1.7;
      color: #374151;
      margin-bottom: 14px;
      overflow-wrap: anywhere;
      word-break: break-word;
    }

    .hit-acceptance__description > *,
    .hit-acceptance__description img,
    .hit-acceptance__description p,
    .hit-acceptance__description ul,
    .hit-acceptance__description ol {
      max-width: 100%;
      width: 100%;
    }

    .hit-acceptance__cost-section {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      padding: 10px 0;
      border-top: 1px solid #f0f0f0;
      margin-top: 14px;
    }

    .hit-acceptance__cost-label {
      font-size: 13px;
      color: #6b7280;
      font-weight: 600;
    }

    .hit-acceptance__cost-value {
      font-size: 20px;
      font-weight: 800;
      color: #111827;
    }

    .hit-acceptance__next-section {
      margin-top: 16px;
      padding-top: 14px;
      border-top: 1px solid #f0f0f0;
    }

    .hit-acceptance__next-label {
      font-size: 11px;
      font-weight: 800;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: #6b7280;
      margin-bottom: 6px;
    }

    .hit-acceptance__next-text {
      font-size: 14px;
      color: #374151;
      line-height: 1.6;
      margin: 0;
    }

    /* ========================================
       FORM LAYOUT
       ======================================== */

    /* Remove sibling margin inside 2-col row — prevents first name input stretching */
    .hit-acceptance--course .hit-field-row .hit-field + .hit-field {
      margin-top: 0;
    }
    </style>

    <script>
    (function () {

      var DEBUG = {{ DEBUG | json }};

      function dbg(label, data) {
        if (!DEBUG) return;
        try { console.log('[course-access] ' + label, data !== undefined ? data : ''); } catch(e) {}
      }

      /* -------------------------------------------------------
         LIQUID VALUES
         ------------------------------------------------------- */
      var _acceptanceId = "{{ acc.hit_offeringacceptanceid | default: '' | escape }}";

      var _cfg = document.getElementById('caConfig');
      var _audience      = _cfg ? _cfg.dataset.audience      : '';
      var _plan          = _cfg ? _cfg.dataset.plan          : '';
      var _audienceValue = _cfg ? _cfg.dataset.audienceValue : '';
      var _planValue     = _cfg ? _cfg.dataset.planValue     : '';
      var _rawPrice      = _cfg ? _cfg.dataset.price         : '0';

      dbg('init', { acceptanceId: _acceptanceId, audience: _audience, plan: _plan });

      /* -------------------------------------------------------
         FIELD GROUP CONFIGURATION
         To add a new audience: add one entry here only.
         ------------------------------------------------------- */
      var AUDIENCE_CONFIG = {
        'individual':          ['contact', 'postcode'],
        'organisation':        ['contact', 'postcode', 'organisation'],
        'organisation-member': ['contact', 'postcode', 'redemption']
      };

      var _activeGroups = AUDIENCE_CONFIG[_audience] || ['contact', 'postcode'];

      /* Activate field groups */
      document.querySelectorAll('[data-field-group]').forEach(function(el) {
        var group = el.dataset.fieldGroup;
        var active = _activeGroups.indexOf(group) !== -1;
        el.hidden = !active;
        /* Disable required on inputs in hidden groups so browser validation doesn't block submit */
        if (!active) {
          el.querySelectorAll('[required]').forEach(function(input) {
            input.removeAttribute('required');
          });
        }
      });

      dbg('activeGroups', _activeGroups);

      /* -------------------------------------------------------
         PRICE DISPLAY
         ------------------------------------------------------- */
      (function() {
        var el = document.getElementById('caPriceDisplay');
        if (!el) return;
        var raw = parseFloat(_rawPrice);
        if (!isNaN(raw) && raw > 0) {
          var cents = Math.round((raw - Math.floor(raw)) * 100);
          el.textContent = '$' + (cents === 0 ? Math.round(raw).toString() : raw.toFixed(2));
        }
      })();

      /* -------------------------------------------------------
         ERROR DISPLAY (donation-style error summary)
         ------------------------------------------------------- */
      var _errSummary = document.getElementById('caErrSummary');
      var _errList    = document.getElementById('caErrList');

      function clearErrors() {
        if (_errSummary) _errSummary.hidden = true;
        if (_errList)    _errList.innerHTML = '';
        document.querySelectorAll('.hit-error-message').forEach(function(p) {
          p.hidden = true;
          p.textContent = '';
        });
        document.querySelectorAll('.hit-input').forEach(function(i) {
          i.setAttribute('aria-invalid', 'false');
        });
      }

      function addError(inputId, errId, message) {
        var input = document.getElementById(inputId);
        var errEl = document.getElementById(errId);
        if (input) input.setAttribute('aria-invalid', 'true');
        if (errEl) { errEl.textContent = message; errEl.hidden = false; }
        if (_errList) {
          var li = document.createElement('li');
          li.textContent = message;
          _errList.appendChild(li);
        }
      }

      function showSummary(firstInputId) {
        if (_errSummary) {
          _errSummary.hidden = false;
          _errSummary.setAttribute('tabindex', '-1');
          _errSummary.focus();
        }
        // Move focus to first invalid field after summary is shown
        var first = document.getElementById(firstInputId);
        if (first) first.focus();
      }

      /* -------------------------------------------------------
         HELPERS
         ------------------------------------------------------- */
      function val(id) {
        var el = document.getElementById(id);
        return el ? el.value.trim() : '';
      }

      function isGroupActive(group) {
        return _activeGroups.indexOf(group) !== -1;
      }

      function setSubmitting(busy) {
        var btn = document.getElementById('caSubmitBtn');
        if (!btn) return;
        btn.disabled = busy;
        btn.textContent = busy ? '{{ submittingButtonText | escape }}' : '{{ submitButtonText | escape }}';
        btn.classList.toggle('is-loading', busy);
      }

      /* -------------------------------------------------------
         CSRF TOKEN (EOI pattern: shell first, tokenhtml fallback)
         Result cached to prevent multiple requests.
         ------------------------------------------------------- */
      var _csrfPromise = null;

      function parseTokenHtml(html) {
        var doc = new DOMParser().parseFromString(html, 'text/html');
        var input = doc.querySelector("input[name='__RequestVerificationToken']");
        return input ? (input.getAttribute('value') || input.value || '').trim() : '';
      }

      async function getCsrfToken() {
        if (_csrfPromise) return _csrfPromise;
        _csrfPromise = (async function() {
          if (window.shell && typeof window.shell.getTokenDeferred === 'function') {
            dbg('CSRF: shell.getTokenDeferred');
            try {
              var t = await new Promise(function(resolve, reject) {
                window.shell.getTokenDeferred()
                  .done(resolve)
                  .fail(function() { reject(new Error('shell.getTokenDeferred failed')); });
              });
              t = (t || '').toString().trim();
              if (t) return t;
            } catch(e) { dbg('CSRF: shell failed, falling back'); }
          }
          dbg('CSRF: /_layout/tokenhtml fallback');
          var res = await fetch('/_layout/tokenhtml', { credentials: 'same-origin' });
          var html = await res.text();
          var tok = parseTokenHtml(html);
          if (!tok) throw new Error('CSRF token not found in /_layout/tokenhtml.');
          return tok;
        })();
        return _csrfPromise;
      }

      /* -------------------------------------------------------
         VALIDATION
         ------------------------------------------------------- */
      function validate() {
        clearErrors();
        var errors = [];

        /* Always required */
        if (!val('caFirstName')) errors.push({ id: 'caFirstName', eid: 'caFirstNameErr', msg: 'First name is required.' });
        if (!val('caLastName'))  errors.push({ id: 'caLastName',  eid: 'caLastNameErr',  msg: 'Last name is required.' });
        if (!val('caEmail'))     errors.push({ id: 'caEmail',     eid: 'caEmailErr',     msg: 'Email address is required.' });
        if (!val('caPostcode'))  errors.push({ id: 'caPostcode',  eid: 'caPostcodeErr',  msg: 'Postcode is required.' });

        /* Audience: organisation */
        if (isGroupActive('organisation')) {
          if (!val('caOrgName')) errors.push({ id: 'caOrgName', eid: 'caOrgNameErr', msg: 'Organisation name is required.' });
          if (!val('caOrgRole')) errors.push({ id: 'caOrgRole', eid: 'caOrgRoleErr', msg: 'Primary contact role is required.' });
        }

        /* Audience: organisation-member */
        if (isGroupActive('redemption')) {
          if (!val('caRedemption')) errors.push({ id: 'caRedemption', eid: 'caRedemptionErr', msg: 'Redemption code is required.' });
        }

        if (errors.length > 0) {
          errors.forEach(function(e) { addError(e.id, e.eid, e.msg); });
          showSummary(errors[0].id);
          return false;
        }
        return true;
      }

      /* -------------------------------------------------------
         API ERROR PARSING
         ------------------------------------------------------- */
      async function parseApiError(res) {
        try {
          var d = await res.json();
          if (d && d.error && d.error.message) return d.error.message;
        } catch(e) {}
        return 'An error occurred. Please try again.';
      }

      /* -------------------------------------------------------
         EXTENSION HOOK — ETrainU integration
         Called after successful PATCH, before redirect.
         Do not implement integrations here — route via Power Automate.
         Replace stub body when ready.

         Integration reference:
           Individual + PWD        → Create Participant, Assign PWD access
           Organisation + Partner  → Create Organisation, Generate Redemption Code
           Org Member + Org Member → Validate Code, Create Participant, Associate to Org
         ------------------------------------------------------- */
      function onAcceptanceSaved(acceptanceId, audience, plan) {
        dbg('onAcceptanceSaved (stub)', { acceptanceId: acceptanceId, audience: audience, plan: plan });
      }

      /* -------------------------------------------------------
         PLATFORM EVENT (EOI convention)
         ------------------------------------------------------- */
      function dispatchSavedEvent(acceptanceId, payload) {
        try {
          window.dispatchEvent(new CustomEvent('hit:acceptance:saved', {
            detail: {
              acceptanceId: acceptanceId,
              payload: payload,
              template: 'sections--acceptance-course',
              audience: _audience,
              plan: _plan
            }
          }));
        } catch(e) {}
      }

      /* -------------------------------------------------------
         REDIRECT — back through router (donation retry pattern)
         Power Automate sets PENDING_PAYMENT or COMPLETED;
         router retry loop detects the status change.
         ------------------------------------------------------- */
      var currentUrl = new URL(window.location.href);
      var waitingForPayment = currentUrl.searchParams.get('waitforpayment') === '1';
      var parsedRouteAttempt = parseInt(currentUrl.searchParams.get('routeattempt') || '0', 10);
      var currentRouteAttempt = Number.isFinite(parsedRouteAttempt) ? parsedRouteAttempt : 0;
      var maximumRouteAttempts = 20;
      var routeRetryDelayMilliseconds = 1250;

      function buildRouterUrl(attempt) {
        return '/accept/?page=offering-acceptance&acceptanceid=' + encodeURIComponent(_acceptanceId)
          + '&waitforpayment=1&routeattempt=' + encodeURIComponent(String(attempt))
          + '&_ts=' + Date.now();
      }

      function redirectToRouter() {
        window.location.replace(buildRouterUrl(0));
      }

      function stopRouterRetry() {
        currentUrl.searchParams.delete('page');
        currentUrl.searchParams.delete('waitforpayment');
        currentUrl.searchParams.delete('routeattempt');
        currentUrl.searchParams.delete('_ts');

        window.history.replaceState({}, document.title, currentUrl.toString());

        setSubmitting(false);

        if (_errList) {
          _errList.innerHTML = '';
          var li = document.createElement('li');
          li.textContent = 'Your details were saved, but the status update is taking longer than expected. Please refresh the page to continue.';
          _errList.appendChild(li);
        }

        if (_errSummary) {
          _errSummary.hidden = false;
          _errSummary.setAttribute('tabindex', '-1');
          _errSummary.focus();
        }
      }

      function retryRouter() {
        if (currentRouteAttempt >= maximumRouteAttempts) {
          stopRouterRetry();
          return;
        }

        setSubmitting(true);

        window.setTimeout(function() {
          window.location.replace(buildRouterUrl(currentRouteAttempt + 1));
        }, routeRetryDelayMilliseconds);
      }

      /* -------------------------------------------------------
         SUBMIT HANDLER
         ------------------------------------------------------- */
      var _submitBtn = document.getElementById('caSubmitBtn');

      if (waitingForPayment) {
        retryRouter();
        return;
      }

      if (_submitBtn) {
        _submitBtn.addEventListener('click', async function() {

          if (!validate()) return;

          setSubmitting(true);

          try {
            var token = await getCsrfToken();

            /* Build payload — always-included fields */
            var payload = {
              hit_firstname:            val('caFirstName'),
              hit_lastname:             val('caLastName'),
              hit_email:                val('caEmail'),
              hit_mobilephone:          val('caMobile') || null,
              hit_postcode:             val('caPostcode'),
              hit_courseaccessaudience: parseInt(_audienceValue, 10) || null,
              hit_courseaccessplan:     parseInt(_planValue,     10) || null
            };

            /* Audience-conditional fields (only from active groups) */
            if (isGroupActive('organisation')) {
              payload.hit_organisationinput = val('caOrgName');
              payload.hit_contactroleinput  = val('caOrgRole');
            }
            if (isGroupActive('redemption')) {
              payload.hit_redemptioncode = val('caRedemption');
            }

            dbg('PATCH payload', payload);

            /* PATCH the existing acceptance record */
            var response = await fetch(
              '/_api/hit_offeringacceptances(' + _acceptanceId + ')',
              {
                method: 'PATCH',
                credentials: 'same-origin',
                headers: {
                  'Content-Type': 'application/json',
                  '__RequestVerificationToken': token,
                  'If-Match': '*'
                },
                body: JSON.stringify(payload)
              }
            );

            if (!response.ok) {
              var errMsg = await parseApiError(response);
              dbg('PATCH failed', { status: response.status, msg: errMsg });
              addError('caFirstName', 'caFirstNameErr', errMsg);
              if (_errList) {
                _errList.innerHTML = '';
                var li = document.createElement('li');
                li.textContent = errMsg;
                _errList.appendChild(li);
              }
              if (_errSummary) { _errSummary.hidden = false; _errSummary.focus(); }
              setSubmitting(false);
              return;
            }

            dbg('PATCH success', '✅ acceptance updated');

            /* Platform event */
            dispatchSavedEvent(_acceptanceId, payload);

            /* ETrainU hook (stub — implement via Power Automate) */
            onAcceptanceSaved(_acceptanceId, _audience, _plan);

            /* Redirect through router — Power Automate handles status */
            redirectToRouter();

          } catch(err) {
            console.error('[course-access] submission error:', err);
            if (_errList) {
              _errList.innerHTML = '';
              var li = document.createElement('li');
              li.textContent = 'An unexpected error occurred. Please try again.';
              _errList.appendChild(li);
            }
            if (_errSummary) { _errSummary.hidden = false; _errSummary.focus(); }
            setSubmitting(false);
          }

        });
      }

    })();
    </script>

  {% endif %}
{% endif %}"
}
